def solve(s):
    # Check if there are any letters in the string
    has_letters = any(c.isalpha() for c in s)

    if not has_letters:
        # Reverse the string if there are no letters
        return s[::-1]
    else:
        # Reverse the case of each letter and leave non-letter characters unchanged
        result = []
        for char in s:
